import { PDFDocument } from 'pdf-lib';

import { db, initializeDatabase } from '../server/db';
// eslint-disable-next-line import/no-unresolved
// @ts-expect-error - TODO: fix type
import { LocalStorageProvider } from '../server/services/storage/LocalStorageProvider';
import * as schema from '../shared/schema';


const TEMPLATE_ID = 'ee86b75f-bac8-4f51-9b40-129227cd6d81';

async function debugExtraction() {
    await initializeDatabase();
    console.log(`Fetching templates...`);
    const allTemplates = await db.select().from(schema.templates);
    console.log(`Found ${allTemplates.length} templates.`);

    const template = allTemplates.find(t => t.id === TEMPLATE_ID) ?? allTemplates.find(t => t.name.includes("4317"));

    if (!template) {
        console.error("Template 'Form 4317' not found in dump.");
        console.log("Available names:", allTemplates.map(t => t.name).slice(0, 5));
        return;
    }

    console.log(`Template found: ${template.name}, fileRef: ${template.fileRef}`);

    if (!template.fileRef) {
        console.error("No fileRef");
        return;
    }

    const storage = new LocalStorageProvider();
    const buffer = await storage.download(template.fileRef);

    console.log("Loading PDF...");
    const pdfDoc = await PDFDocument.load(buffer);
    const form = pdfDoc.getForm();
    const fields = form.getFields();
    const pages = pdfDoc.getPages();

    console.log(`PDF has ${pages.length} pages and ${fields.length} fields.`);

    // Log page references
    console.log("--- PAGES ---");
    pages.forEach((p, i) => {
        const ref = p.ref;
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        // @ts-expect-error - TODO: fix type
        console.log(`Page ${i}: tag=${ref.tag}, gen=${ref.gen}, objectNumber=${(ref as any).objectNumber}, generationNumber=${(ref as any).generationNumber}`);
    });

    console.log("--- FIELDS ---");
    const pageCounts: Record<number, number> = {};

    for (const field of fields) {
        const name = field.getName();
        const widgets = field.acroField.getWidgets();

        widgets.forEach((w, wi) => {
            const pRef = w.P();

            let pageIndex = pages.findIndex(p => {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                const pTag = p.ref.tag ?? (p.ref as any).objectNumber;
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                // @ts-expect-error - TODO: fix type
                const wTag = pRef.tag ?? (pRef as any).objectNumber;
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                // @ts-expect-error - TODO: fix type
                const pGen = p.ref.gen ?? (p.ref as any).generationNumber;
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                // @ts-expect-error - TODO: fix type
                const wGen = pRef.gen ?? (pRef as any).generationNumber;
                return pTag === wTag && pGen === wGen;
            });

            if (pageIndex === -1) {
                // Try identity
                pageIndex = pages.findIndex(p => p.ref === pRef);
            }

            if (pageIndex === -1) {
                // eslint-disable-next-line @typescript-eslint/no-explicit-any
                // @ts-expect-error - TODO: fix type
                console.log(`Field ${name} widget ${wi} FAILED to match any page. P() ref: tag=${pRef.tag}, obj=${(pRef as any).objectNumber}`);
            } else {
                pageCounts[pageIndex] = (pageCounts[pageIndex] ?? 0) + 1;
                if (pageIndex === 1) { // Page 2
                    console.log(`Field on Page 2: ${name}`);
                }
            }
        });
    }

    console.log("--- SUMMARY ---");
    console.log("Page counts:", JSON.stringify(pageCounts, null, 2));
}

debugExtraction().catch((error: unknown) => {
  console.error('Error:', error instanceof Error ? error.message : String(error));
}).finally(() => process.exit());

import { eq } from 'drizzle-orm';

import { db, initializeDatabase } from '../server/db';

import { getPdfFieldExtractor } from '../server/services/document/extractors/PdfFieldExtractor';
// eslint-disable-next-line import/no-unresolved
// @ts-expect-error - TODO: fix type
import { LocalStorageProvider } from '../server/services/storage/LocalStorageProvider';
import * as schema from '../shared/schema';

// Hardcoded template ID from user logs
const _TEMPLATE_ID = 'ee86b75f-bac8-4f51-9b40-129227cd6d81';
// Wait, the log said `blob:http://localhost:5000/ee86...`. Is that the template ID?
// User request Step 32: `GET http://localhost:5000/api/sections/4471a74b...`
// Let's search for the template first.

async function fixTemplate() {
    await initializeDatabase();
    console.log('Searching for templates...');
    // We'll search by checking which one has fields.
    // Actually, let's just list all templates and update all of them? 
    // Or just the one the user is looking at.
    // The user uploaded `uploaded_image_1766432690146.png` showing Form 4317.
    // We can search for a template named "4317" or similar.

    // Use 'templates' table
    const templateList = await db.select().from(schema.templates);

    console.log(`Found ${templateList.length} templates.`);

    const storage = new LocalStorageProvider();

    for (const template of templateList) {
        console.log(`Processing template: ${template.name} (${template.id})`);

        // To keep this script simple and self-contained, I might need to import the storage service too.

        if (!template.fileRef) {
            console.log('No fileRef, skipping.');
            continue;
        }

        try {
            console.log(`Downloading file from storage: ${template.fileRef}`);
            const buffer = await storage.download(template.fileRef);

            console.log('Extracting fields...');
            const extractor = getPdfFieldExtractor();
            const metadata = await extractor.extract(buffer);

            console.log(`Extracted ${metadata.fields.length} fields.`);
            const pageIndices = new Set(metadata.fields.map(f => f.pageIndex));
            console.log('Page indices found:', Array.from(pageIndices));

            // Update the template
            await db.update(schema.templates)
                .set({
                    metadata: metadata,
                    updatedAt: new Date()
                })
                .where(eq(schema.templates.id, template.id));

            console.log('Updated template metadata.');
        } catch (err: unknown) {
            console.error('Failed to process template:', err instanceof Error ? err.message : String(err));
        }
    }
}

fixTemplate().then(() => {
    console.log('Done.');
    process.exit(0);
}).catch((err: unknown) => {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
});

