/* eslint-disable @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-call, @typescript-eslint/no-unsafe-return, @typescript-eslint/no-unsafe-argument */
import { eq, and } from "drizzle-orm";
import { z } from "zod";

import { tenants, users, projects } from "@shared/schema";

import { db } from "../db";
import { createLogger } from "../logger";
import { hybridAuth, type AuthRequest } from "../middleware/auth";
import { requireOwner, requirePermission } from "../middleware/rbac";
import { requireTenant, validateTenantParam } from "../middleware/tenant";
import { invalidateUserCache } from "../middleware/userCache";
import { userRepository } from "../repositories";
import { authService } from "../services/AuthService";
import { asyncHandler } from "../utils/asyncHandler";

import type { Express, Request, Response } from "express";



const logger = createLogger({ module: 'tenant-routes' });

/**
 * Register tenant-related routes
 * Provides APIs for tenant management and access control
 */
export function registerTenantRoutes(app: Express): void {
  /**
   * GET /api/tenants/current
   * Get the current user's tenant information
   */
  app.get('/api/tenants/current', hybridAuth, requireTenant, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const tenantId = authReq.tenantId;

      if (!tenantId) {
        return res.status(404).json({
          message: 'No tenant found for current user',
          error: 'no_tenant',
        });
      }

      // Get tenant information
      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, tenantId));

      // eslint-disable-next-line @typescript-eslint/strict-boolean-expressions
      if (!tenant) {
        return res.status(404).json({
          message: 'Tenant not found',
          error: 'tenant_not_found',
        });
      }

      res.json({
        id: tenant.id,
        name: tenant.name,
        billingEmail: tenant.billingEmail,
        plan: tenant.plan,
        createdAt: tenant.createdAt,
        updatedAt: tenant.updatedAt,
      });
    } catch (error) {
      logger.error({ error }, 'Failed to fetch current tenant');
      res.status(500).json({
        message: 'Failed to fetch tenant',
        error: 'internal_error',
      });
    }
  }));

  /**
   * GET /api/tenants/:tenantId
   * Get specific tenant information (must be a member of the tenant)
   */
  app.get('/api/tenants/:tenantId', hybridAuth, validateTenantParam, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;

      // Get tenant information
      const [tenant] = await db
        .select()
        .from(tenants)
        .where(eq(tenants.id, tenantId));

      // eslint-disable-next-line @typescript-eslint/strict-boolean-expressions
      if (!tenant) {
        return res.status(404).json({
          message: 'Tenant not found',
          error: 'tenant_not_found',
        });
      }

      res.json({
        id: tenant.id,
        name: tenant.name,
        billingEmail: tenant.billingEmail,
        plan: tenant.plan,
        createdAt: tenant.createdAt,
        updatedAt: tenant.updatedAt,
      });
    } catch (error) {
      logger.error({ error }, 'Failed to fetch tenant');
      res.status(500).json({
        message: 'Failed to fetch tenant',
        error: 'internal_error',
      });
    }
  }));

  /**
   * PUT /api/tenants/:tenantId
   * Update tenant information (owner only)
   */
  app.put('/api/tenants/:tenantId', hybridAuth, validateTenantParam, requireOwner, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;
      const UpdateTenantSchema = z.object({
        name: z.string().min(1).optional(),
        billingEmail: z.string().email().optional(),
      }).strict();

      const parsed = UpdateTenantSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({
          message: 'Invalid request body',
          error: 'validation_error',
          details: parsed.error.errors
        });
      }

      const { name, billingEmail } = parsed.data;

      // Validate input
      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- dynamic update fields for tenant
      const updateData: any = {
        updatedAt: new Date(),
      };

      if (name !== undefined) { updateData.name = name; }
      if (billingEmail !== undefined) { updateData.billingEmail = billingEmail; }

      // Update tenant
      const [updatedTenant] = await db
        .update(tenants)
        .set(updateData)
        .where(eq(tenants.id, tenantId))
        .returning();

      // eslint-disable-next-line @typescript-eslint/strict-boolean-expressions
      if (!updatedTenant) {
        return res.status(404).json({
          message: 'Tenant not found',
          error: 'tenant_not_found',
        });
      }

      logger.info({ tenantId }, 'Tenant updated');

      res.json({
        message: 'Tenant updated successfully',
        tenant: {
          id: updatedTenant.id,
          name: updatedTenant.name,
          billingEmail: updatedTenant.billingEmail,
          plan: updatedTenant.plan,
          updatedAt: updatedTenant.updatedAt,
        },
      });
    } catch (error) {
      logger.error({ error }, 'Failed to update tenant');
      res.status(500).json({
        message: 'Failed to update tenant',
        error: 'internal_error',
      });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/users
   * Get all users in a tenant (owner or builder)
   */
  app.get('/api/tenants/:tenantId/users', hybridAuth, validateTenantParam, requirePermission('tenant:view'), asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;

      // Get all users in the tenant
      const tenantUsers = await db
        .select({
          id: users.id,
          email: users.email,
          firstName: users.firstName,
          lastName: users.lastName,
          fullName: users.fullName,
          profileImageUrl: users.profileImageUrl,
          role: users.tenantRole,
          authProvider: users.authProvider,
          createdAt: users.createdAt,
        })
        .from(users)
        .where(eq(users.tenantId, tenantId));

      res.json({
        users: tenantUsers,
        total: tenantUsers.length,
      });
    } catch (error) {
      logger.error({ error }, 'Failed to fetch tenant users');
      res.status(500).json({
        message: 'Failed to fetch users',
        error: 'internal_error',
      });
    }
  }));

  /**
   * GET /api/tenants/:tenantId/projects
   * Get all projects in a tenant
   */
  app.get('/api/tenants/:tenantId/projects', hybridAuth, validateTenantParam, requirePermission('project:view'), asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId } = req.params;

      // Get all projects in the tenant
      const tenantProjects = await db
        .select()
        .from(projects)
        .where(eq(projects.tenantId, tenantId));

      res.json({
        projects: tenantProjects,
        total: tenantProjects.length,
      });
    } catch (error) {
      logger.error({ error }, 'Failed to fetch tenant projects');
      res.status(500).json({
        message: 'Failed to fetch projects',
        error: 'internal_error',
      });
    }
  }));

  /**
   * POST /api/tenants
   * Create a new tenant (for future multi-tenant signup)
   */
  app.post('/api/tenants', hybridAuth, asyncHandler(async (req: Request, res: Response) => {
    try {
      const authReq = req as AuthRequest;
      const { name, billingEmail } = req.body;

      // Validate input
      if (!name) {
        return res.status(400).json({
          message: 'Tenant name is required',
          error: 'missing_fields',
        });
      }

      // Create tenant
      const [newTenant] = await db
        .insert(tenants)
        .values({
          name,
          billingEmail: billingEmail ?? null,
          plan: 'free',
        })
        .returning();

      // Update user's tenantId and role to owner
      if (authReq.userId) {
        await userRepository.updateUser(authReq.userId, {
          tenantId: newTenant.id,
          tenantRole: 'owner',
        });
      }

      logger.info({ tenantId: newTenant.id, userId: authReq.userId }, 'Tenant created');

      res.status(201).json({
        message: 'Tenant created successfully',
        tenant: {
          id: newTenant.id,
          name: newTenant.name,
          billingEmail: newTenant.billingEmail,
          plan: newTenant.plan,
          createdAt: newTenant.createdAt,
        },
      });
    } catch (error) {
      logger.error({ error }, 'Failed to create tenant');
      res.status(500).json({
        message: 'Failed to create tenant',
        error: 'internal_error',
      });
    }
  }));

  /**
   * PUT /api/tenants/:tenantId/users/:userId/role
   * Update user role in tenant (owner only)
   */
  app.put('/api/tenants/:tenantId/users/:userId/role', hybridAuth, validateTenantParam, requireOwner, asyncHandler(async (req: Request, res: Response) => {
    try {
      const { tenantId, userId } = req.params;
      const { role } = req.body;

      // Validate role
      const validRoles = ['owner', 'builder', 'runner', 'viewer'];
      if (!role || !validRoles.includes(role)) {
        return res.status(400).json({
          message: 'Invalid role. Must be one of: owner, builder, runner, viewer',
          error: 'invalid_role',
        });
      }

      // SECURITY: scope the UPDATE to the tenant so an owner can only change roles of users
      // that actually belong to their tenant. Previously the update matched on id alone and
      // only checked tenantId AFTER writing — letting an owner of tenant A mutate a user in
      // tenant B (the write persisted even though a 403 was returned).
      const [updatedUser] = await db
        .update(users)
        .set({
          tenantRole: role,
          updatedAt: new Date(),
        })
        .where(and(eq(users.id, userId), eq(users.tenantId, tenantId)))
        .returning();

      // eslint-disable-next-line @typescript-eslint/strict-boolean-expressions
      if (!updatedUser) {
        // Either the user does not exist or does not belong to this tenant. Do not
        // distinguish the two, to avoid leaking cross-tenant user existence.
        return res.status(404).json({
          message: 'User not found in this tenant',
          error: 'user_not_found',
        });
      }

      // SECURITY: a role change must take effect immediately. Invalidate the cached user (so
      // JWT-based auth re-hydrates the new role at once) and revoke the user's refresh tokens
      // (so their session cannot be silently refreshed under the old role).
      invalidateUserCache(userId);
      await authService.revokeAllUserTokens(userId);

      logger.info({ tenantId, userId, newRole: role }, 'User role updated');

      res.json({
        message: 'User role updated successfully',
        user: {
          id: updatedUser.id,
          email: updatedUser.email,
          firstName: updatedUser.firstName,
          lastName: updatedUser.lastName,
          role: updatedUser.tenantRole,
        },
      });
    } catch (error) {
      logger.error({ error }, 'Failed to update user role');
      res.status(500).json({
        message: 'Failed to update user role',
        error: 'internal_error',
      });
    }
  }));
}

import { nanoid } from 'nanoid';
import { v4 as uuidv4 } from 'uuid';

import type { Workflow, WorkflowVersion } from '../../shared/schema';

/**
 * Graph Factory
 * Helpers to create valid Graph-based Workflows and Runs for testing.
 *
 * NOTE: The visual graph engine (server/engine) has been removed. These local
 * type shims preserve the legacy graphJson fixture shape still used by the
 * analytics and snapshot integration tests, without depending on engine code.
 */
interface QuestionNodeConfig {
    key: string;
    question?: string;
    [key: string]: unknown;
}

interface Node {
    id: string;
    type: string;
    config: Record<string, unknown>;
}

interface GraphJson {
    nodes: Node[];
    edges: Array<{ id: string; source: string; target: string }>;
    startNodeId: string;
}

export const createNodeId = (prefix: string = 'node') => `${prefix}_${nanoid(6)}`;

export function createQuestionNode(
    id: string,
    question: string,
    type: 'short_text' | 'yes_no' | 'multiple_choice' = 'short_text',
    options: Record<string, unknown> = {}
): Node {
    return {
        id,
        type: 'question',
        // @ts-expect-error - TODO: fix type
        config: {
            key: id,
            question,
            
            ...options,
        } as QuestionNodeConfig,
    };
}

export function createGraph(nodes: Node[] = []): GraphJson {
    if (nodes.length === 0) {
        const startNode = createQuestionNode('start', 'Start Question');
        nodes.push(startNode);
    }

    // Auto-generate edges for a simple linear flow if no edges provided
    // This is a simplification for basic tests
    const edges = [];
    for (let i = 0; i < nodes.length - 1; i++) {
        edges.push({
            id: `edge_${i}`,
            source: nodes[i].id,
            target: nodes[i + 1].id,
        });
    }

    return {
        nodes,
        edges,
        startNodeId: nodes[0].id,
    };
}

export function createGraphWorkflow(
    overrides: Partial<Workflow> = {},
    graphOverrides: Partial<GraphJson> = {}
): { workflow: Workflow; version: WorkflowVersion } {
    const workflowId = uuidv4();
    const versionId = uuidv4();
    const now = new Date();

    const overridesAny = overrides as Record<string, unknown>;
    const creatorId = overridesAny.createdBy as string ?? overridesAny.creatorId as string ?? uuidv4();
    const ownerId = overridesAny.ownerId as string ?? creatorId;

    const workflow: Workflow = {
        id: workflowId,
        projectId: uuidv4(),
        title: overrides.title ?? overridesAny.name as string ?? 'Test Graph Workflow',
        description: 'Generated by graphFactory',
        creatorId,
        ownerId,
        createdAt: now,
        updatedAt: now,
        ...overrides,
    } as Workflow;

    // Remove invalid keys if they leaked in from overrides
    delete (workflow as Record<string, unknown>).name;
    delete (workflow as Record<string, unknown>).status;

    const graph = createGraph(graphOverrides.nodes);

    const version: WorkflowVersion = {
        id: versionId,
        workflowId: workflowId,
        graphJson: graph,
        versionNumber: 1,
        isDraft: true,
        createdBy: creatorId,
        createdAt: now,
        updatedAt: now,
        published: false,
    } as WorkflowVersion;

    return { workflow, version };
}

import _fs from "fs/promises";
import _path from "path";

import { eq } from "drizzle-orm";
import { nanoid } from "nanoid";
import request from "supertest";
import { vi , describe, it, expect, beforeAll, afterAll, beforeEach } from "vitest";

import * as schema from "@shared/schema";

import { db } from "../../server/db";
import { setupIntegrationTest, type IntegrationTestContext } from "../helpers/integrationTestHelper";
// Mock template scanner to avoid parsing invalid zip files
vi.mock("../../server/services/document/TemplateScanner", () => ({
  templateScanner: {
    scan: vi.fn().mockResolvedValue({
      placeholders: ["{{name}}", "{{date}}"],
      isValid: true
    }),
    scanAndFix: vi.fn().mockResolvedValue({
      placeholders: ["{{name}}", "{{date}}"],
      isValid: true,
      fixed: false,
      buffer: Buffer.from("PK\x03\x04"),
      repairs: []
    }),
    extractPlaceholders: vi.fn().mockResolvedValue(["{{name}}", "{{date}}"])
  }
}));
// Mock services/templates to avoid parsing invalid docx files
vi.mock("../../server/services/templates", async () => {
  const actual = await vi.importActual<typeof import("../../server/services/templates")>("../../server/services/templates");
  return {
    ...actual,
    saveTemplateFile: vi.fn().mockImplementation(async () => {
      return `test-file-${Math.random().toString(36).substring(7)}.docx`;
    }),
    deleteTemplateFile: vi.fn().mockResolvedValue(undefined),
    templateFileExists: vi.fn().mockResolvedValue(true),
    extractPlaceholders: vi.fn().mockResolvedValue(["{{name}}", "{{date}}"]),
    validateTemplate: vi.fn().mockResolvedValue({ valid: true, missingVars: [], extraVars: [] }),
  };
});
/**
 * Templates and Runs API Integration Tests
 *
 * Refactored to use integrationTestHelper for consistent setup/teardown
 */
describe("Templates API Integration Tests", () => {
  let ctx: IntegrationTestContext;
  let workflowId: string;
  beforeAll(async () => {
    // Use integration test helper for consistent setup
    ctx = await setupIntegrationTest({
      tenantName: "Test Tenant for Templates",
      createProject: true,
      projectName: "Test Project",
      userRole: "admin",
      tenantRole: "owner",
    });
    // Create and publish workflow
    const workflowResponse = await request(ctx.baseURL)
      .post(`/api/workflows`)
      .set("Authorization", `Bearer ${ctx.authToken}`)
      .send({
        title: "Test Workflow",
        projectId: ctx.projectId,
      })
      .expect(201);
    workflowId = workflowResponse.body.id;
    await request(ctx.baseURL)
      .post(`/api/workflows/${workflowId}/publish`)
      .set("Authorization", `Bearer ${ctx.authToken}`)
      .send({ graphJson: { pages: [] } })
      .expect(200);
  });
  afterAll(async () => {
    await ctx.cleanup();
  });
  describe("Templates API", () => {
    describe("POST /api/projects/:ctx.projectId/templates", () => {
      it("should create template with file upload", async () => {
